(function () {

  // 🔥 0. HARD RESET GLOBAL (OBLIGATOIRE)
  if (window._examTimer) {
    clearInterval(window._examTimer);
    window._examTimer = null;
  }

  window._examTimerRunning = false;

  // 🔄 Reset visuel du temps
  wwLib.wwVariable.updateValue(
    'ba74a8e8-51e5-4159-8f3e-53bd4c7592ee', // examElapsedSeconds
    0
  );

  // 🚫 1. IGNORE TIMER AVANT DÉMARRAGE
  if (wwLib.wwVariable.getValue('ignoreTimer') === true) {
    console.warn('⏭ Timer ignored — not starting');
    return;
  }

  // 🔒 2. HARD LOCK (sécurité ultime)
  if (window._examTimerRunning === true) {
    console.warn('⛔ Timer already running — abort');
    return;
  }

  console.log('✅ Starting exam timer');

  window._examTimerRunning = true;
  const startTime = Date.now();

  // ⏱️ 3. SEUL ENDROIT OÙ LE TEMPS AVANCE
  window._examTimer = setInterval(() => {

    // 🛑 STOP SI IGNORE ACTIVÉ APRÈS DÉMARRAGE
    if (wwLib.wwVariable.getValue('ignoreTimer') === true) {
      console.warn('🛑 Timer stopped (ignoreTimer)');
      clearInterval(window._examTimer);
      window._examTimer = null;
      window._examTimerRunning = false;
      return;
    }

    const elapsed = Math.floor((Date.now() - startTime) / 1000);

    wwLib.wwVariable.updateValue(
      'ba74a8e8-51e5-4159-8f3e-53bd4c7592ee', // examElapsedSeconds
      elapsed
    );

  }, 1000);

})();
